    #[derive(Clone, Copy, Debug)]
    pub struct Point {
        pub x: u16,
        pub y: u16,
        pub z: i8,
    }
    impl ToWit for Point {
        fn to_wit(&self) -> Value {
            let mut o = crate::p1::call::Map::new();
            o.insert("x".into(), self.x.to_wit());
            o.insert("y".into(), self.y.to_wit());
            o.insert("z".into(), self.z.to_wit());
            Value::Object(o)
        }
    }
    impl FromWit for Point {
        fn from_wit(v: &Value) -> Option<Self> {
            Some(Self {
                x: FromWit::from_wit(crate::p1::call::field(v, "x"))?,
                y: FromWit::from_wit(crate::p1::call::field(v, "y"))?,
                z: FromWit::from_wit(crate::p1::call::field(v, "z"))?,
            })
        }
    }
    #[derive(Clone, Copy, Debug)]
    pub enum Destination {
        /// Into a container; the server picks the slot.
        Container(Serial),
        /// Into a container at a slot (x, y).
        ContainerAt((Serial, u16, u16,)),
        /// On the ground.
        Ground(Point),
    }
    impl ToWit for Destination {
        fn to_wit(&self) -> Value {
            let (k, v) = match self {
                Self::Container(p) => ("container", p.to_wit()),
                Self::ContainerAt(p) => ("container-at", p.to_wit()),
                Self::Ground(p) => ("ground", p.to_wit()),
            };
            crate::p1::call::variant(k, v)
        }
    }
    impl FromWit for Destination {
        fn from_wit(v: &Value) -> Option<Self> {
            let (k, p) = crate::p1::call::case(v)?;
            Some(match k {
                "container" => Self::Container(FromWit::from_wit(p)?),
                "container-at" => Self::ContainerAt(FromWit::from_wit(p)?),
                "ground" => Self::Ground(FromWit::from_wit(p)?),
                _ => return None,
            })
        }
    }
